<template>
  <div class="mc">
    <div class="mc-accent-bar" :style="{ background: theme.bar }"></div>
    <div class="mc-top">
      <div class="mc-titles">
        <div class="mc-title">{{ title }}</div>
        <div v-if="subtitle" class="mc-sub">{{ subtitle }}</div>
      </div>
      <div
          class="mc-pct-badge"
          :style="{ background: theme.factBg, color: theme.pctColor, border: `1px solid ${theme.factBorder}` }"
      >
        {{ fulfillment }}%
      </div>
    </div>
    <div class="mc-body">
      <div class="rw">
        <svg viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg" width="100" height="100">
          <defs>
            <linearGradient :id="gradientId" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" :stop-color="theme.strokeLight"/>
              <stop offset="100%" :stop-color="theme.strokeDark"/>
            </linearGradient>
          </defs>
          <circle cx="50" cy="50" r="44" fill="none" :stroke="theme.track" stroke-width="8"/>
          <circle
              cx="50" cy="50" r="44"
              fill="none"
              :stroke="`url(#${gradientId})`"
              stroke-width="8"
              stroke-linecap="round"
              :stroke-dasharray="circumference"
              :stroke-dashoffset="dashOffset"
              transform="rotate(-90 50 50)"
              class="ring-progress"
          />
        </svg>
        <div class="ring-center">
          <span class="ring-pct" :style="{ color: theme.pctColor }">{{ fulfillment }}%</span>
          <span class="ring-label">выполн.</span>
        </div>
      </div>

      <div class="metrics">
        <div class="metric-row plan-row">
          <span class="metric-label">План</span>
          <span class="metric-value">{{ plan.toLocaleString() }}</span>
        </div>
        <div
            class="metric-row"
            :style="{ background: theme.factBg, border: `1px solid ${theme.factBorder}` }"
        >
          <span class="metric-label">Факт</span>
          <span class="metric-value" :style="{ color: theme.pctColor }">{{ fact.toLocaleString() }}</span>
        </div>
        <div class="metric-divider"></div>
        <div class="metric-row-ly">
          <span class="metric-label-ly">Факт пр. год</span>
          <span class="metric-value-ly">{{ formatAmount(factLastYear) }}</span>
        </div>
      </div>
    </div>
    <div class="mc-footer">
      <span class="yoy-badge" :style="yoyStyle">{{ yoyLabel }}</span>
    </div>
  </div>
</template>

<script>
import {dataStore} from "@/operations/requests";

export default {
  name: 'MetricCard',

  data() {
    return {
      gradientId: 'ring-' + Math.random().toString(36).slice(2, 7), // уникальный ID
      title: '',
      subtitle: '',
      fact: 0,
      plan: 0,
      factLastYear: 0,

      maxFill: 100,           // при каком % кольцо заполнено полностью
      amountFormat: 'short',  // 'short' (тыс/млн) | 'currency' (₴)
      circumference: 2 * Math.PI * 44,
      animated: false,
    }
  },

  mounted() {
    this.setData();

    requestAnimationFrame(() => {
      this.animated = true
    })
  },

  computed: {
    fulfillment() {
      if (!this.plan) return 0
      return Math.round((this.fact / this.plan) * 100)
    },

    dashOffset() {
      if (!this.animated) return this.circumference
      return this.circumference * (1 - Math.min(this.fulfillment / this.maxFill, 1))
    },

    theme() {
      if (this.fulfillment >= 100) {
        return {
          bar: 'linear-gradient(90deg,#22c55e,#4ade80)',
          strokeDark: '#16a34a',
          strokeLight: '#4ade80',
          track: '#dcfce7',
          pctColor: '#16a34a',
          factBg: '#f0fdf4',
          factBorder: '#bbf7d0',
        }
      }
      if (this.fulfillment >= 85) {
        return {
          bar: 'linear-gradient(90deg,#f59e0b,#fcd34d)',
          strokeDark: '#d97706',
          strokeLight: '#fde68a',
          track: '#fef3c7',
          pctColor: '#d97706',
          factBg: '#fffbeb',
          factBorder: '#fde68a',
        }
      }
      return {
        bar: 'linear-gradient(90deg,#ef4444,#fca5a5)',
        strokeDark: '#dc2626',
        strokeLight: '#fca5a5',
        track: '#fee2e2',
        pctColor: '#dc2626',
        factBg: '#fff5f5',
        factBorder: '#fecaca',
      }
    },

    yoyChange() {
      if (!this.factLastYear) return null
      return Math.round(((this.fact - this.factLastYear) / this.factLastYear) * 100)
    },

    yoyLabel() {
      if (this.yoyChange === null) return '—'
      return (this.yoyChange > 0 ? '▲ +' : '▼ ') + this.yoyChange + '% к пр. году'
    },

    yoyStyle() {
      if (this.yoyChange === null) return 'background:#f3f4f6;color:#9ba3b8'
      return this.yoyChange > 0
          ? 'background:#dcfce7;color:#15803d;border:1px solid #bbf7d0'
          : 'background:#fee2e2;color:#b91c1c;border:1px solid #fecaca'
    },
  },

  methods: {
    setData() {
      let payload = dataStore.getCompanyData();
      this.title = 'Услуги и страховки';
      this.subtitle = payload[0].time;
      this.fact = payload[0].services_f;
      this.plan = payload[0].services_p;
      this.factLastYear = payload[0].services_past;
    },

    formatAmount(val) {
      if (val == null) return '—'
      if (this.amountFormat === 'currency') {
        return new Intl.NumberFormat('uk-UA', {
          style: 'currency',
          currency: 'UAH',
          maximumFractionDigits: 0,
        }).format(val)
      }
      if (Math.abs(val) >= 1_000_000) return (val / 1_000_000).toFixed(2).replace('.', ',') + '\u00a0млн'
      if (Math.abs(val) >= 1_000) return (val / 1_000).toFixed(1).replace('.', ',') + '\u00a0тыс'
      return val.toLocaleString('ru-RU')
    },
  },
}
</script>

<style scoped>
.mc {
  max-width: 350px;
  min-width: 300px;
  width: 100%;
  border-radius: 18px;
  background: #ffffff;
  box-shadow: 0 0 10px rgb(0 0 0 / 0.3);
  overflow: hidden;
  font-family: 'Inter', system-ui, sans-serif;
}

.mc-accent-bar {
  height: 4px;
  width: 100%;
}

.mc-top {
  padding: 16px 18px 12px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.mc-title {
  font-size: 15px;
  font-weight: 700;
  color: #1a1f36;
  letter-spacing: -0.3px;
}

.mc-sub {
  font-size: 11px;
  color: #9ba3b8;
  margin-top: 2px;
  font-weight: 500;
}

.mc-pct-badge {
  font-size: 12px;
  font-weight: 700;
  padding: 4px 9px;
  border-radius: 20px;
  white-space: nowrap;
  flex-shrink: 0;
}

.mc-body {
  padding: 0 18px 14px;
  display: flex;
  align-items: center;
  gap: 14px;
}

.rw {
  position: relative;
  width: 100px;
  height: 100px;
  flex-shrink: 0;
}

.ring-progress {
  transition: stroke-dashoffset 0.8s cubic-bezier(0.4, 0, 0.2, 1);
}

.ring-center {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.ring-pct {
  font-size: 20px;
  font-weight: 800;
  line-height: 1;
  letter-spacing: -1px;
}

.ring-label {
  font-size: 9px;
  color: #9ba3b8;
  letter-spacing: 0.6px;
  text-transform: uppercase;
  margin-top: 3px;
  font-weight: 600;
}

.metrics {
  display: flex;
  flex-direction: column;
  gap: 5px;
  width: 60%;
  margin-left: auto;
}

.metric-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 7px 10px;
  border-radius: 10px;
}

.plan-row {
  background: #f7f8fb;
  border: 1px solid #eef0f5;
}

.metric-label {
  font-size: 11px;
  font-weight: 600;
  color: #9ba3b8;
}

.metric-value {
  font-size: 14px;
  font-weight: 700;
  color: #1a1f36;
  letter-spacing: -0.3px;
}

.metric-divider {
  height: 1px;
  background: #f0f2f7;
  margin: 2px 0;
}

.metric-row-ly {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 2px 10px;
}

.metric-label-ly {
  font-size: 11px;
  color: #b8bfce;
  font-weight: 500;
}

.metric-value-ly {
  font-size: 12px;
  font-weight: 600;
  color: #b8bfce;
}

.mc-footer {
  padding: 0 18px 16px;
}

.yoy-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 700;
  padding: 5px 10px;
  border-radius: 20px;
}
</style>