<template>
  <div class="main-data-container">
    <!-- ── 1. Лёгкий прелоадер (данные уже есть в кеше) ── -->
    <transition name="fade">
      <div class="light-preloader" v-if="isCacheLoad">
        <div class="lp-bar">
          <div class="lp-bar-fill"></div>
        </div>
        <div class="lp-text">Подготовка данных...</div>
      </div>
    </transition>

    <!-- ── 2. Полный степпер (первая загрузка) ─────────── -->
    <div class="loader-wrap" v-if="!isLoad && !isCacheLoad">

      <!-- Орбитальный спиннер до начала прогресса -->
      <div class="spinner-only" v-if="!isPogress">
        <div class="orbit-spinner">
          <div class="orbit"></div>
          <div class="orbit"></div>
          <div class="orbit"></div>
        </div>
      </div>

      <!-- Степпер -->
      <div class="stepper-load" v-if="isPogress">
        <div class="top-bar">
          <div class="top-bar-fill" :style="{ width: progressWidth }"></div>
        </div>
        <div class="loader-title">Загрузка, пожалуйста подождите...</div>
        <div class="steps">
          <template v-for="(step, i) in loaderSteps" :key="step.key">
            <div v-if="i > 0" class="step-line">
              <div class="step-line-fill" :style="{ width: lineWidth(i) }"></div>
            </div>
            <div class="step">
              <div class="step-icon" :class="stepState(step.key)">
                <div v-if="stepState(step.key) === 'active'" class="step-spinner"></div>
                <span v-else-if="stepState(step.key) === 'done'">✓</span>
                <span v-else class="step-arrow">↓</span>
              </div>
              <div class="step-label" :class="stepState(step.key)">{{ step.label }}</div>
            </div>
          </template>
        </div>
      </div>
    </div>

    <!-- ── 3. Контент ─────────────────────────────────── -->
    <transition name="fade">
      <div class="main-data-body" v-if="isLoad">
        <div class="cards">
          <CardProductComponent :selected-date="userTimeDate"/>
          <CardServicesComponent :selected-date="userTimeDate"/>
          <CardTraficComponent :selected-date="userTimeDate"/>
          <CardConversionComponent :selected-date="userTimeDate"/>
          <CardCheckComponent :selected-date="userTimeDate"/>
          <CardCountComponent :selected-date="userTimeDate"/>
          <CardCreditComponent :selected-date="userTimeDate"/>
        </div>
        <div class="divider"></div>
        <div class="charts">
          <AllManagersChart/>
          <div class="divider"></div>
          <TraficManagerChart/>
          <div class="divider"></div>
          <div class="secondary-manager-charts">
            <CheckManagersChart/>
            <ConverciaManagersChart/>
          </div>
          <div class="divider"></div>

          <div class="secondary-manager-charts">
            <CreditManagerChart/>
            <CountManagersChart/>
          </div>
        </div>
      </div>
    </transition>

    <v-snackbar v-model="snackbar" color="error" timeout="4000">
      {{ snackbarText }}
    </v-snackbar>
  </div>
</template>

<script>
import {dataStore} from '@/operations/requests'
import $ from 'jquery'

import CardProductComponent from '@/components/others/CardProductComponent.vue'
import CardServicesComponent from '@/components/others/CardServicesComponent.vue'
import CardTraficComponent from '@/components/others/CardTraficComponent.vue'
import CardConversionComponent from '@/components/others/CardConversionComponent.vue'
import CardCheckComponent from '@/components/others/CardCheckComponent.vue'
import CardCountComponent from '@/components/others/CardCountComponent.vue'
import CardCreditComponent from '@/components/others/CardCreditComponent.vue'

import AllManagersChart from "@/components/chart/AllManagersChart.vue";
import CheckManagersChart from "@/components/chart/CheckManagersChart.vue";
import ConverciaManagersChart from "@/components/chart/ConverciaManagersChart.vue";
import CreditManagerChart from "@/components/chart/CreditManagerChart.vue";
import TraficManagerChart from "@/components/chart/TraficManagerChart.vue";
import CountManagersChart from "@/components/chart/CountManagersChart.vue";

export default {
  name: 'MainDataComponent',
  components: {
    CardProductComponent,
    CardServicesComponent,
    CardTraficComponent,
    CardConversionComponent,
    CardCheckComponent,
    CardCountComponent,
    CardCreditComponent,
    AllManagersChart,
    CheckManagersChart,
    ConverciaManagersChart,
    CreditManagerChart,
    TraficManagerChart,
    CountManagersChart
  },
  data() {
    return {
      screenWidth: window.innerWidth,
      isLoad: false,   // контент показан
      isPogress: false,   // степпер активен
      isCacheLoad: false,   // лёгкий прелоадер (возврат с кешем)
      snackbar: false,
      snackbarText: '',

      companyData: [],
      stadnikData: [],
      dudinaData: [],
      ambrosovData: [],
      artutjanData: [],
      mjaskovskiyData: [],

      //------- for props-date
      userTimeDate: new Date().toLocaleString(),

      loadPersonalData: {
        company: false,
        stadnik: false,
        dudina: false,
        ambrosov: false,
        artutjan: false,
        mjaskovskiy: false,
      },
      loaderSteps: [
        {key: 'company', label: 'Компания'},
        {key: 'stadnik', label: 'Стадник'},
        {key: 'dudina', label: 'Дудина'},
        {key: 'ambrosov', label: 'Амбросов'},
        {key: 'artutjan', label: 'Артутян'},
        {key: 'mjaskovskiy', label: 'Мясковский'},
      ],
    }
  },
  computed: {
    progressWidth() {
      const done = Object.values(this.loadPersonalData).filter(Boolean).length
      return Math.round((done / this.loaderSteps.length) * 100) + '%'
    },
  },
  methods: {
    stepState(key) {
      if (this.loadPersonalData[key]) return 'done'
      const keys = Object.keys(this.loadPersonalData)
      const firstPending = keys.find(k => !this.loadPersonalData[k])
      return firstPending === key ? 'active' : 'pending'
    },
    lineWidth(i) {
      const keys = Object.keys(this.loadPersonalData)
      const prevKey = keys[i - 1]
      if (this.loadPersonalData[prevKey]) return '100%'
      const firstPending = keys.find(k => !this.loadPersonalData[k])
      return firstPending === prevKey ? '40%' : '0%'
    },
    async getRequest() {
      const cached = dataStore.getCompanyData()

      if (cached) {
        // ── Данные уже есть — лёгкий прелоадер, без степпера
        this.isCacheLoad = true
        setTimeout(() => {
          this.isCacheLoad = false
          this.isLoad = true
          localStorage.setItem('checkLoadStatus', 'loaded')
        }, 600)
        return
      }

      // ── Первая загрузка — полный степпер
      this.isPogress = true
      try {
        await $.ajax({
          url: 'https://script.google.com/macros/s/AKfycbyopRoKlGbWKz64b2CAunvasw3mesUYGC9brnH10R-nuywlx2YlOzETj6aJ2aQU1fWP/exec',
          type: 'GET',
          crossDomain: true,
          dataType: 'json',
          success: (response) => {
            dataStore.setCompanyData(response.info);
            this.companyData = [...response.info];
            this.loadPersonalData.company = true
          },
          error: (error) => {
            this.snackbarText = 'Ошибка загрузки данных по компании'
            this.snackbar = true
            console.error(error)
          },
        })
        await $.ajax({
          url: 'https://script.google.com/macros/s/AKfycbwx6XXBUswZZO2lra9x7ky2Khvpdcfg8eNowXs9H4bZ36kOlDU2UkpH8t5cYj2yqe8vPQ/exec',
          type: 'GET',
          crossDomain: true,
          dataType: 'json',
          success: (response) => {
            dataStore.setStadnikData(response.stad_info);
            this.stadnikData = [...response.stad_info];
            this.loadPersonalData.stadnik = true
          },
          error: (error) => {
            this.snackbarText = 'Ошибка загрузки данных Стадника'
            this.snackbar = true
            console.error(error)
          },
        })
        await $.ajax({
          url: 'https://script.google.com/macros/s/AKfycbxrHrKBaMh9kFAn4IDe8pIte2P_kjww4OFX7nmZi9gE6kQ8t_WtO8Bktpcnz3EzuB_6Gg/exec',
          type: 'GET',
          crossDomain: true,
          dataType: 'json',
          success: (response) => {
            dataStore.setDudinaData(response.dud_info);
            this.dudinaData = [...response.dud_info];
            this.loadPersonalData.dudina = true;
          },
          error: (error) => {
            this.snackbarText = 'Ошибка загрузки данных Дудиной'
            this.snackbar = true
            console.error(error)
          },
        })
        await $.ajax({
          url: 'https://script.google.com/macros/s/AKfycbySTGlgvTE9Kx1kL_W5wo59RjPCE7FbmdnnoSa-KTSWLAjW4-GGEYnS5AdMer-7x1zo/exec',
          type: 'GET',
          crossDomain: true,
          dataType: 'json',
          success: (response) => {
            dataStore.setAmbrosovData(response.ambr_info);
            this.ambrosovData = [...response.ambr_info];
            this.loadPersonalData.ambrosov = true;
          },
          error: (error) => {
            this.snackbarText = 'Ошибка загрузки данных Амбросова'
            this.snackbar = true
            console.error(error)
          },
        })
        await $.ajax({
          url: 'https://script.google.com/macros/s/AKfycby1ALl8dz_CdR4Tv_HsTFsKs2VfRvKK4ceqKN7xQLdm_YMNpVF5z2dBc3yI2FTiOCb8pQ/exec',
          type: 'GET',
          crossDomain: true,
          dataType: 'json',
          success: (response) => {
            dataStore.setArtutjanData(response.art_info);
            this.artutjanData = [...response.art_info];
            this.loadPersonalData.artutjan = true;
          },
          error: (error) => {
            this.snackbarText = 'Ошибка загрузки данных Артутяна'
            this.snackbar = true
            console.error(error)
          },
        })
        await $.ajax({
          url: 'https://script.google.com/macros/s/AKfycbzJw0bQyVKyHsSZe2D2Ps36s6l0ssSmHZjPEONP4Og0Hp1OP1GnhYl4SW7xXGbOVOGB/exec',
          type: 'GET',
          crossDomain: true,
          dataType: 'json',
          success: (response) => {
            dataStore.setMjaskovskiyData(response.mjas_info);
            this.mjaskovskiyData = [...response.mjas_info];
            this.loadPersonalData.mjaskovskiy = true;
          },
          error: (error) => {
            this.snackbarText = 'Ошибка загрузки данных Мясковского'
            this.snackbar = true
            console.error(error)
          },
        })
      } catch (e) {
        console.error(e)
      }
    },
    updateWidth() {
      this.screenWidth = window.innerWidth
    },
  },
  watch: {
    loadPersonalData: {
      handler(val) {
        if (Object.values(val).every(Boolean)) {
          setTimeout(() => {
            this.isLoad = true
            localStorage.setItem('checkLoadStatus', 'loaded');
          }, 800)
        }
      },
      deep: true,
    },
  },
  created() {
    window.addEventListener('resize', this.updateWidth)
  },
  mounted() {
    this.getRequest()
  },
  beforeUnmount() {
    window.removeEventListener('resize', this.updateWidth)
    localStorage.removeItem('checkLoadStatus')
  },
}
</script>

<style lang="scss" scoped>
.main-data-container {
  width: 100%;
  min-height: 200px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

// ── Fade-переход для контента и прелоадера ──────────
.fade-enter-active {
  transition: opacity 0.4s ease;
}

.fade-leave-active {
  transition: opacity 0.25s ease;
}

.fade-enter-from, .fade-leave-to {
  opacity: 0;
}

// ── Лёгкий прелоадер (кеш) ─────────────────────────
.light-preloader {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  padding: 60px 20px;
}

.lp-bar {
  width: 200px;
  height: 3px;
  background: #f0f2f7;
  border-radius: 2px;
  overflow: hidden;
}

.lp-bar-fill {
  height: 100%;
  border-radius: 2px;
  background: linear-gradient(90deg, #f97316, #fbbf24);
  animation: lp-sweep 0.6s ease forwards;
}

@keyframes lp-sweep {
  from {
    width: 0;
  }
  to {
    width: 100%;
  }
}

.lp-text {
  font-size: 12px;
  font-weight: 600;
  color: #9ba3b8;
  letter-spacing: 0.4px;
}

// ── Орбитальный спиннер ─────────────────────────────
.spinner-only {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 60px;
}

.orbit-spinner {
  width: 56px;
  height: 56px;
  position: relative;

  .orbit {
    position: absolute;
    inset: 0;
    border-radius: 50%;
    border: 3px solid transparent;
    animation: orbit-spin 1.2s linear infinite;

    &:nth-child(1) {
      border-top-color: #f97316;
      animation-duration: 1.0s;
    }

    &:nth-child(2) {
      inset: 8px;
      border-right-color: #fbbf24;
      animation-duration: 1.4s;
      animation-direction: reverse;
    }

    &:nth-child(3) {
      inset: 16px;
      border-bottom-color: #f97316;
      animation-duration: 1.8s;
    }
  }
}

@keyframes orbit-spin {
  to {
    transform: rotate(360deg);
  }
}

// ── Обёртка степпера ────────────────────────────────
.loader-wrap {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 20px;
}

.stepper-load {
  max-width: 780px;
  width: 100%;
  background: rgba(255, 255, 255, 0.72);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.8);
  border-radius: 20px;
  padding: 28px 32px 24px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.04), 0 12px 28px rgba(0, 0, 0, 0.08);
  position: relative;
  overflow: hidden;
}

.top-bar {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: #f0f2f7;
}

.top-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, #f97316, #fb923c, #fbbf24);
  border-radius: 0 2px 2px 0;
  transition: width 0.5s ease;
  position: relative;

  &::after {
    content: '';
    position: absolute;
    right: 0;
    top: 50%;
    transform: translateY(-50%);
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #f97316;
    box-shadow: 0 0 8px rgba(249, 115, 22, 0.6);
  }
}

.loader-title {
  font-size: 13px;
  font-weight: 600;
  color: #6b7280;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  gap: 8px;

  &::before {
    content: '';
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: #f97316;
    box-shadow: 0 0 6px rgba(249, 115, 22, 0.5);
    animation: dot-pulse 1.2s ease-in-out infinite;
    flex-shrink: 0;
  }
}

@keyframes dot-pulse {
  0%, 100% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.4;
    transform: scale(0.7);
  }
}

.steps {
  display: flex;
  align-items: center;
}

.step {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  flex: 0 0 auto;
}

.step-line {
  flex: 1;
  height: 2px;
  background: #e5e7eb;
  position: relative;
  margin-bottom: 28px;
  min-width: 20px;

  .step-line-fill {
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    background: linear-gradient(90deg, #f97316, #fbbf24);
    border-radius: 1px;
    transition: width 0.5s ease;
  }
}

.step-icon {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 700;
  transition: all 0.4s ease;
  background: #f3f4f6;
  border: 2px solid #e5e7eb;
  color: #9ca3af;

  &.done {
    background: linear-gradient(135deg, #f97316, #fbbf24);
    border-color: transparent;
    color: #fff;
    box-shadow: 0 4px 12px rgba(249, 115, 22, 0.35);
  }

  &.active {
    background: #fff;
    border-color: #f97316;
    color: #f97316;
    animation: ring-pulse 1.2s ease-in-out infinite;
  }
}

@keyframes ring-pulse {
  0%, 100% {
    box-shadow: 0 0 0 4px rgba(249, 115, 22, 0.12);
  }
  50% {
    box-shadow: 0 0 0 8px rgba(249, 115, 22, 0.05);
  }
}

.step-spinner {
  width: 18px;
  height: 18px;
  border: 2px solid rgba(249, 115, 22, 0.2);
  border-top-color: #f97316;
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

.step-label {
  font-size: 11px;
  font-weight: 600;
  color: #9ca3af;
  transition: color 0.3s;
  white-space: nowrap;

  &.done {
    color: #1a1f36;
  }

  &.active {
    color: #f97316;
  }
}


// ── Контент ─────────────────────────────────────────
.main-data-body {
  width: 100%;

  .cards {
    display: flex;
    flex-direction: row;
    justify-content: center;
    gap: 30px;
    flex-wrap: wrap;
    margin: 50px auto 0;
  }

  .divider {
    width: 80%;
    margin: 50px auto;
    height: 3px;
    border-radius: 1px;
    background-image: linear-gradient(to right, transparent, rgba(255, 165, 0, 0.5), transparent);
  }

  .charts{
    width: 100%;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;

    .secondary-manager-charts{
      width: 100%;
      display: flex;
      flex-direction: row;
      justify-content: center;
      gap: 30px;
      flex-wrap: wrap;
      margin: 0 auto;
    }
  }
}
</style>