<template>
  <div class="chart-card">
    <div class="chart-header">
      <div>
        <div class="chart-tag">Средний чек</div>
        <h2 class="chart-title">Сравнение чека по менеджерам</h2>
        <p class="chart-subtitle">{{ period }}</p>
      </div>
    </div>
    <div class="cr-legend">
      <div class="cr-leg-item">
        <div class="cr-leg-dot" style="background:#6366f1"></div>
        Факт
      </div>
      <div class="cr-leg-item">
        <div class="cr-leg-dot" style="background:rgba(99,102,241,.2);border:1.5px dashed #6366f155"></div>
        План
      </div>
      <div class="cr-leg-item">
        <div class="cr-leg-dot" style="background:#e2e8f0"></div>
        Пр. год
      </div>
    </div>
    <div class="check-rows">
      <div v-for="m in managers" :key="m.name" class="check-row">
        <div class="cr-name">{{ m.name }}</div>
        <div class="cr-bars">
          <div class="cr-bar-wrap">
            <div class="cr-bar" :style="{ width: barW(m.check_f), background: m.color + 'dd' }"></div>
            <span class="cr-bar-label" :style="{ color: m.color }">
              {{ m.check_f.toLocaleString('ru-RU') }}
            </span>
          </div>
          <div class="cr-bar-wrap">
            <div class="cr-bar" :style="{ width: barW(m.check_p), background: 'rgba(99,102,241,.15)', border: '1.5px dashed rgba(99,102,241,.35)' }"></div>
            <span class="cr-bar-label" style="color:#94a3b8">{{ m.check_p.toLocaleString('ru-RU') }}</span>
          </div>
          <div class="cr-bar-wrap">
            <div class="cr-bar" :style="{ width: barW(m.check_past), background: '#e2e8f0' }"></div>
            <span class="cr-bar-label" style="color:#94a3b8">{{ m.check_past.toLocaleString('ru-RU') }}</span>
          </div>
        </div>
        <div class="cr-pct" :style="{ color: pctColor(m.pct) }">{{ m.pct }}%</div>
      </div>
    </div>
  </div>
</template>

<script>
import { dataStore } from '@/operations/requests'
const MANAGER_COLORS = {
  'Стадник':    '#6366f1',
  'Дудина':     '#22c55e',
  'Амбросов':   '#f59e0b',
  'Артутян':    '#ef4444',
  'Мясковский': '#14b8a6',
}

function pctColor(p) {
  if (p >= 100) return '#22c55e'
  if (p >= 90)  return '#84cc16'
  if (p >= 80)  return '#f59e0b'
  return '#ef4444'
}

export default {
  name: 'CheckChartComponent',
  data() {
    return {
      managers: [],
      period:   '',
      maxVal:   0,
    }
  },

  mounted() {
    this.setData()
  },

  methods: {
    setData() {
      const sources = [
        { name: 'Стадник',    data: dataStore.getStadnikData()     },
        { name: 'Дудина',     data: dataStore.getDudinaData()      },
        { name: 'Амбросов',   data: dataStore.getAmbrosovDataa()   },
        { name: 'Артутян',    data: dataStore.getArtutjanData()    },
        { name: 'Мясковский', data: dataStore.getMjaskovskiyData() },
      ]

      const result = sources
          .filter(s => s.data && s.data[0])
          .map(s => {
            const row = s.data[0]
            const pct = row.check_p
                ? Math.round((row.check_f / row.check_p) * 100)
                : 0
            return {
              name:       s.name,
              color:      MANAGER_COLORS[s.name] || '#94a3b8',
              check_f:    row.check_f,
              check_p:    row.check_p,
              check_past: row.check_past,
              pct,
            }
          })

      this.managers = result.sort((a, b) => b.check_f - a.check_f)
      this.period   = sources.find(s => s.data?.[0])?.data[0].time || ''
      this.maxVal   = Math.max(...result.flatMap(m => [m.check_f, m.check_p, m.check_past])) * 1.1
    },
    barW(val) {
      return Math.min((val / this.maxVal) * 100, 100) + '%'
    },
    pctColor,
  },
}
</script>

<style scoped>
.chart-card {
  background: #ffffff;
  border-radius: 20px;
  border: 1px solid rgba(0, 0, 0, 0.06);
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.04), 0 12px 28px rgba(0, 0, 0, 0.07);
  padding: 22px 24px;
  font-family: 'Inter', system-ui, sans-serif;
  width: 100%;
  max-width: 700px;
  min-width: 350px;
}

.chart-header {
  margin-bottom: 16px;
}

.chart-tag {
  display: inline-block;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: #f59e0b;
  background: rgba(245, 158, 11, 0.1);
  border: 1px solid rgba(245, 158, 11, 0.2);
  padding: 3px 10px;
  border-radius: 20px;
  margin-bottom: 5px;
}

.chart-title {
  font-size: 17px;
  font-weight: 700;
  color: #1e293b;
  letter-spacing: -0.3px;
  margin: 0 0 2px;
}

.chart-subtitle {
  font-size: 11px;
  color: #94a3b8;
  font-weight: 500;
  margin: 0;
}

.cr-legend {
  display: flex;
  gap: 14px;
  margin-bottom: 14px;
  flex-wrap: wrap;
}

.cr-leg-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: #64748b;
  font-weight: 500;
}

.cr-leg-dot {
  width: 12px;
  height: 12px;
  border-radius: 3px;
  flex-shrink: 0;
}

.check-rows {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.check-row {
  display: grid;
  grid-template-columns: 90px 1fr 52px;
  align-items: center;
  gap: 6px;
}

.cr-name {
  font-size: 12px;
  font-weight: 600;
  color: #475569;
  text-align: right;
}

.cr-bars {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.cr-bar-wrap {
  display: flex;
  align-items: center;
  gap: 8px;
}

.cr-bar {
  height: 10px;
  border-radius: 6px;
  transition: width 0.6s ease;
  min-width: 4px;
  flex-shrink: 0;
}

.cr-bar-label {
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
}

.cr-pct {
  font-size: 13px;
  font-weight: 800;
  text-align: right;
}
</style>
