<template>
  <div class="chart-card">
    <div class="chart-header">
      <div class="chart-tag">Кол-во позиций в чеке</div>
      <h2 class="chart-title">Количество позиций в чеке</h2>
      <p class="chart-subtitle">{{ period }}</p>
    </div>

    <div class="legend">
      <div class="leg-item">
        <span class="leg-dot-fact"></span>
        Факт
      </div>
      <div class="leg-item">
        <span class="leg-dot-past"></span>
        Пр. год
      </div>
      <div class="leg-item">
        <span class="leg-plan-line"></span>
        Ср. план
      </div>
    </div>

    <!-- SVG-график -->
    <div class="chart-wrap">
      <svg
          class="main-svg"
          :viewBox="`0 0 ${W} ${H}`"
          xmlns="http://www.w3.org/2000/svg"
          preserveAspectRatio="xMidYMid meet"
      >
        <defs>
          <filter id="dot-shadow" x="-60%" y="-60%" width="220%" height="220%">
            <feDropShadow dx="0" dy="4" stdDeviation="5" flood-color="rgba(0,0,0,0.18)"/>
          </filter>
        </defs>

        <!-- ── Горизонтальные линии сетки ── -->
        <g v-for="v in gridVals" :key="v">
          <line
              :x1="PL" :y1="toY(v)"
              :x2="W - PR" :y2="toY(v)"
              stroke="rgba(148,163,184,0.18)"
              stroke-width="1"
          />
          <text
              :x="PL - 8" :y="toY(v) + 4"
              font-size="11"
              fill="#cbd5e1"
              font-family="Inter, system-ui"
              font-weight="500"
              text-anchor="end"
          >{{ v.toFixed(1) }}</text>
        </g>

        <!-- ── Линия среднего плана ── -->
        <line
            :x1="PL" :y1="planY"
            :x2="W - PR" :y2="planY"
            stroke="rgba(99,102,241,0.5)"
            stroke-width="1.5"
            stroke-dasharray="6 3"
        />
        <text
            :x="W - PR + 4" :y="planY + 4"
            font-size="9"
            fill="#6366f1"
            font-family="Inter, system-ui"
            font-weight="700"
        >ср. план {{ avgPlan }}</text>

        <!-- ── Lollipops ── -->
        <g v-for="m in chartManagers" :key="m.name">

          <!-- Палочка от низа до кружка -->
          <line
              :x1="m.cx" :y1="PB_Y"
              :x2="m.cx" :y2="m.cy + DOT_R"
              :stroke="m.color + '66'"
              stroke-width="2.5"
              stroke-linecap="round"
          />

          <!-- Точка прошлого года -->
          <circle
              :cx="m.cx"
              :cy="m.pastCy"
              r="6"
              :fill="m.color + '55'"
              stroke="white"
              stroke-width="1.5"
          />

          <!-- Основной кружок -->
          <circle
              :cx="m.cx"
              :cy="m.cy"
              :r="DOT_R"
              :fill="m.color"
              stroke="white"
              stroke-width="3"
              filter="url(#dot-shadow)"
          />

          <!-- % внутри кружка -->
          <text
              :x="m.cx" :y="m.cy + 5"
              font-size="11"
              font-weight="800"
              fill="white"
              text-anchor="middle"
              font-family="Inter, system-ui"
          >{{ m.pct }}%</text>

          <!-- Значение факта над кружком -->
          <text
              :x="m.cx" :y="m.cy - DOT_R - 8"
              font-size="13"
              font-weight="800"
              :fill="m.color"
              text-anchor="middle"
              font-family="Inter, system-ui"
          >{{ m.count_f.toFixed(2) }}</text>

        </g>
      </svg>

      <!-- ── Имена и бейджи под графиком ── -->
      <div class="names-row">
        <div
            v-for="m in chartManagers"
            :key="m.name"
            class="name-cell"
        >
          <span class="name-text">{{ m.name }}</span>
          <span
              class="yoy-badge"
              :style="m.yoy >= 0
              ? 'background:#dcfce7;color:#16a34a'
              : 'background:#fee2e2;color:#dc2626'"
          >
            {{ m.yoy >= 0 ? '▲ +' : '▼ ' }}{{ m.yoy }}%
          </span>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { dataStore } from '@/operations/requests'

const MANAGER_COLORS = {
  'Стадник':    '#6366f1',
  'Дудина':     '#22c55e',
  'Амбросов':   '#f59e0b',
  'Артутян':    '#ef4444',
  'Мясковский': '#14b8a6',
}

// Размеры SVG
const W    = 800  // ширина
const H    = 260  // высота
const PL   = 36   // padding left (для подписей оси Y)
const PR   = 70   // padding right (для подписи плана)
const PT   = 40   // padding top (место для значения над кружком)
const PB   = 20   // padding bottom
const DOT_R = 22  // радиус кружка

// Диапазон значений оси Y
const MIN = 1.1
const MAX = 2.05

function toY(val) {
  const drawH = H - PT - PB
  return PT + drawH - ((val - MIN) / (MAX - MIN)) * drawH
}

function pctColor(p) {
  if (p >= 100) return '#22c55e'
  if (p >= 90)  return '#84cc16'
  if (p >= 80)  return '#f59e0b'
  return '#ef4444'
}

export default {
  name: 'CountChartComponent',

  data() {
    return {
      chartManagers: [],
      period:        '',
      avgPlan:       '—',
      planY:         0,
      gridVals:      [1.2, 1.4, 1.6, 1.8, 2.0],
      W, H, PL, PR, PT, PB, DOT_R,
      PB_Y: H - PB,  // Y нижней точки палочки
    }
  },

  mounted() {
    this.setData()
  },

  methods: {
    setData() {
      const sources = [
        { name: 'Стадник',    data: dataStore.getStadnikData()     },
        { name: 'Дудина',     data: dataStore.getDudinaData()      },
        { name: 'Амбросов',   data: dataStore.getAmbrosovDataa()   },
        { name: 'Артутян',    data: dataStore.getArtutjanData()    },
        { name: 'Мясковский', data: dataStore.getMjaskovskiyData() },
      ]

      const result = sources
          .filter(s => s.data && s.data[0])
          .map(s => {
            const row = s.data[0]
            const pct = row.count_p
                ? Math.round((row.count_f / row.count_p) * 100)
                : 0
            const yoy = row.count_past
                ? Math.round(((row.count_f - row.count_past) / row.count_past) * 100)
                : 0
            return {
              name:       s.name,
              color:      MANAGER_COLORS[s.name] || '#94a3b8',
              count_f:    row.count_f,
              count_p:    row.count_p,
              count_past: row.count_past,
              pct,
              yoy,
            }
          })
          .sort((a, b) => b.count_f - a.count_f)

      // Средний план
      const avg    = result.reduce((s, m) => s + m.count_p, 0) / result.length
      this.avgPlan = avg.toFixed(2)
      this.planY   = toY(avg)
      this.period  = sources.find(s => s.data?.[0])?.data[0].time || ''

      // X-позиции
      const drawW = W - PL - PR
      const step  = drawW / result.length

      this.chartManagers = result.map((m, i) => ({
        ...m,
        cx:     PL + step * i + step / 2,
        cy:     toY(m.count_f),
        pastCy: toY(m.count_past),
      }))
    },

    toY,
    pctColor,
  },
}
</script>

<style scoped>
.chart-card {
  background: #ffffff;
  border-radius: 20px;
  border: 1px solid rgba(0, 0, 0, 0.06);
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.04), 0 12px 28px rgba(0, 0, 0, 0.07);
  padding: 22px 24px;
  font-family: 'Inter', system-ui, sans-serif;
  width: 100%;
  max-width: 700px;
  min-width: 350px;
}

.chart-header { margin-bottom: 16px; }

.chart-tag {
  display: inline-block;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: #ec4899;
  background: rgba(236, 72, 153, 0.08);
  border: 1px solid rgba(236, 72, 153, 0.2);
  padding: 3px 10px;
  border-radius: 20px;
  margin-bottom: 5px;
}

.chart-title {
  font-size: 17px;
  font-weight: 700;
  color: #1e293b;
  letter-spacing: -0.3px;
  margin: 0 0 2px;
}

.chart-subtitle {
  font-size: 11px;
  color: #94a3b8;
  font-weight: 500;
  margin: 0;
}

/* ── Легенда ───────────────────────────────────────── */
.legend {
  display: flex;
  gap: 14px;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.leg-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: #64748b;
  font-weight: 500;
}

.leg-dot-fact {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #6366f1;
  border: 2px solid #fff;
  box-shadow: 0 0 0 1.5px #6366f1;
  display: inline-block;
  flex-shrink: 0;
}

.leg-dot-past {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #94a3b8;
  opacity: 0.55;
  display: inline-block;
  flex-shrink: 0;
}

.leg-plan-line {
  width: 20px;
  height: 0;
  border-top: 2px dashed rgba(99, 102, 241, 0.5);
  display: inline-block;
  flex-shrink: 0;
}

/* ── SVG ───────────────────────────────────────────── */
.chart-wrap { width: 100%; }

.main-svg {
  width: 100%;
  overflow: visible;
  display: block;
}

/* ── Имена ─────────────────────────────────────────── */
.names-row {
  display: flex;
  padding: 0 70px 0 36px;
  margin-top: 4px;
}

.name-cell {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.name-text {
  font-size: 11px;
  font-weight: 600;
  color: #475569;
  text-align: center;
}

.yoy-badge {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 10px;
  display: inline-block;
}
</style>
