<template>
  <div class="chart-card">
    <div class="chart-header">
      <div class="chart-header__left">
        <div class="chart-tag">Сводный анализ</div>
        <h2 class="chart-title">Товарооборот и выполнение плана</h2>
        <p class="chart-subtitle">{{ period }}</p>
      </div>
      <div class="chart-header__legend">
        <div class="legend-item">
          <span class="legend-bar" style="background: linear-gradient(135deg,#22c55e,#f59e0b)"></span>
          Факт (грн)
        </div>
        <div class="legend-item">
          <span class="legend-bar" style="background: rgba(148,163,184,0.6)"></span>
          Факт пр. год (грн)
        </div>
        <div class="legend-item">
          <span class="legend-line"></span>
          % выполнения
        </div>
      </div>
    </div>
    <div class="chart-wrap">
      <canvas ref="chartCanvas"></canvas>
    </div>
    <div class="managers-row">
      <div
          v-for="m in managers"
          :key="m.name"
          class="manager-chip"
          :style="{ borderColor: m.color + '55', background: m.color + '11' }"
      >
        <span class="chip-dot" :style="{ background: m.color }"></span>
        <span class="chip-name">{{ m.name }}</span>
        <span class="chip-pct" :style="{ color: m.color }">{{ m.pct }}%</span>
      </div>
    </div>
  </div>
</template>

<script>
import { Chart, registerables } from 'chart.js'
import { dataStore } from '@/operations/requests'
Chart.register(...registerables)
function pctColor(pct) {
  if (pct >= 100) return '#22c55e'
  if (pct >= 90)  return '#84cc16'
  if (pct >= 80)  return '#f59e0b'
  if (pct >= 70)  return '#f97316'
  return '#ef4444'
}

function fmtMln(v) {
  if (v == null) return '—'
  if (Math.abs(v) >= 1e6) return (v / 1e6).toFixed(2).replace('.', ',') + ' млн'
  if (Math.abs(v) >= 1e3) return (v / 1e3).toFixed(0) + ' тыс'
  return String(v)
}

export default {
  name: 'ManagersChartComponent',
  data() {
    return {
      chartInstance: null,
      managers: [],
      period: '',
    }
  },
  mounted() {
    this.buildChart()
  },
  beforeUnmount() {
    if (this.chartInstance) {
      this.chartInstance.destroy()
    }
  },
  methods: {
    getData() {
      const sources = [
        { name: 'Стадник',    data: dataStore.getStadnikData()     },
        { name: 'Дудина',     data: dataStore.getDudinaData()      },
        { name: 'Амбросов',   data: dataStore.getAmbrosovDataa()   },
        { name: 'Артутян',    data: dataStore.getArtutjanData()    },
        { name: 'Мясковский', data: dataStore.getMjaskovskiyData() },
      ]

      return sources
          .filter(s => s.data && s.data[0])
          .map(s => {
            const row = s.data[0]
            const pct = row.products_p
                ? Math.round((row.products_f / row.products_p) * 100)
                : 0
            return {
              name:  s.name,
              fact:  row.products_f,
              past:  row.products_past,
              pct,
              color: pctColor(pct),
              time:  row.time,
            }
          })
    },

    buildChart() {
      const raw = this.getData()
      if (!raw.length) return

      raw.sort((a, b) => b.fact - a.fact)

      this.managers = raw
      this.period   = raw[0]?.time || ''

      const labels = raw.map(m => m.name)
      const facts  = raw.map(m => m.fact)
      const pasts  = raw.map(m => m.past)
      const pcts   = raw.map(m => m.pct)
      const colors = raw.map(m => m.color)

      const barLabelsPlugin = {
        id: 'barLabels',
        afterDatasetsDraw(chart) {
          const { ctx: c, data } = chart

          // ── Подписи на столбцах ФАКТ ──────────────────
          const barMeta = chart.getDatasetMeta(0)
          barMeta.data.forEach((bar, i) => {
            const pct   = data.datasets[2].data[i]
            const color = data.datasets[0].borderColor[i]

            // Пилюля с % выполнения
            const text = pct + '%'
            c.save()
            c.font = 'bold 11px system-ui'
            const tw = c.measureText(text).width + 14
            const th = 20, tx = bar.x, ty = bar.y + 18
            c.beginPath()
            c.fillStyle = color + 'dd'
            c.roundRect(tx - tw / 2, ty - th / 2, tw, th, th / 2)
            c.fill()
            c.fillStyle = '#fff'
            c.textAlign = 'center'
            c.textBaseline = 'middle'
            c.fillText(text, tx, ty)
            c.restore()

            // Сумма факта над столбцом
            c.save()
            c.fillStyle = '#1e293b'
            c.font = '600 11px system-ui'
            c.textAlign = 'center'
            c.textBaseline = 'bottom'
            c.fillText(fmtMln(data.datasets[0].data[i]), bar.x, bar.y - 6)
            c.restore()
          })

          // ── Подписи на столбцах ПРОШЛЫЙ ГОД ──────────
          const pastMeta = chart.getDatasetMeta(1)
          pastMeta.data.forEach((bar, i) => {
            const pastVal = data.datasets[1].data[i]
            const factVal = data.datasets[0].data[i]

            // Сумма прошлого года
            c.save()
            c.fillStyle = '#94a3b8'
            c.font = '500 10px system-ui'
            c.textAlign = 'center'
            c.textBaseline = 'bottom'
            c.fillText(fmtMln(pastVal), bar.x, bar.y - 24)
            c.restore()

            // Бейдж прироста к прошлому году
            if (pastVal && factVal) {
              const growth  = Math.round(((factVal - pastVal) / pastVal) * 100)
              const isPos   = growth >= 0
              const text    = (isPos ? '▲ +' : '▼ ') + growth + '%'
              const color   = isPos ? '#16a34a' : '#dc2626'
              const bgColor = isPos ? 'rgba(34,197,94,0.15)' : 'rgba(239,68,68,0.15)'

              c.save()
              c.font = 'bold 10px system-ui'
              const tw = c.measureText(text).width + 10
              const th = 16
              const tx = bar.x
              const ty = bar.y - 6

              c.beginPath()
              c.fillStyle = bgColor
              c.roundRect(tx - tw / 2, ty - th, tw, th, th / 2)
              c.fill()

              c.fillStyle = color
              c.textAlign = 'center'
              c.textBaseline = 'middle'
              c.fillText(text, tx, ty - th / 2)
              c.restore()
            }
          })
        },
      }

      const ctx = this.$refs.chartCanvas.getContext('2d')

      this.chartInstance = new Chart(ctx, {
        data: {
          labels,
          datasets: [
            // ── Столбцы — факт ──────────────────────────
            {
              type: 'bar',
              label: 'Факт (грн)',
              data: facts,
              backgroundColor: colors.map(c => c + 'bb'),
              borderColor:     colors,
              borderWidth: 2,
              borderRadius: 10,
              borderSkipped: false,
              yAxisID: 'yFact',
              order: 2,
            },
            // ── Столбцы — прошлый год ───────────────────
            {
              type: 'bar',
              label: 'Факт пр. год (грн)',
              data: pasts,
              backgroundColor: 'rgba(148,163,184,0.3)',
              borderColor:     'rgba(148,163,184,0.65)',
              borderWidth: 2,
              borderRadius: 10,
              borderSkipped: false,
              yAxisID: 'yFact',
              order: 3,
            },
            // ── Линия — % выполнения ────────────────────
            {
              type: 'line',
              label: '% выполнения',
              data: pcts,
              borderColor: '#6366f1',
              backgroundColor: 'rgba(99,102,241,0.06)',
              borderWidth: 2.5,
              pointBackgroundColor: colors,
              pointBorderColor: '#fff',
              pointBorderWidth: 2,
              pointRadius: 7,
              pointHoverRadius: 10,
              tension: 0.4,
              fill: true,
              yAxisID: 'yPct',
              order: 1,
            },
          ],
        },

        options: {
          responsive: true,
          maintainAspectRatio: false,
          interaction: { mode: 'index', intersect: false },

          plugins: {
            legend: { display: false },
            tooltip: {
              backgroundColor: 'rgba(15,23,42,0.92)',
              titleColor: '#e2e8f0',
              bodyColor: '#94a3b8',
              borderColor: 'rgba(255,255,255,0.08)',
              borderWidth: 1,
              padding: 14,
              cornerRadius: 12,
              titleFont: { size: 13, weight: '700' },
              bodyFont: { size: 12 },
              callbacks: {
                label(ctx) {
                  if (ctx.datasetIndex === 0) return `  Факт: ${fmtMln(ctx.parsed.y)}`
                  if (ctx.datasetIndex === 1) {
                    const pastVal = ctx.parsed.y
                    const factVal = ctx.chart.data.datasets[0].data[ctx.dataIndex]
                    const growth  = pastVal ? Math.round(((factVal - pastVal) / pastVal) * 100) : 0
                    const sign    = growth >= 0 ? '+' : ''
                    return `  Пр. год: ${fmtMln(pastVal)}  (${sign}${growth}% к пр. году)`
                  }
                  return `  Выполнение: ${ctx.parsed.y}%`
                },
              },
            },
          },

          scales: {
            x: {
              grid: { display: false },
              border: { display: false },
              ticks: { color: '#64748b', font: { size: 12, weight: '600' } },
            },
            yFact: {
              type: 'linear',
              position: 'left',
              grid: { color: 'rgba(148,163,184,0.12)' },
              border: { display: false },
              ticks: {
                color: '#64748b',
                font: { size: 11 },
                callback(v) {
                  if (v >= 1e6) return (v / 1e6).toFixed(1) + ' млн'
                  if (v >= 1e3) return (v / 1e3).toFixed(0) + ' тыс'
                  return v
                },
              },
            },
            yPct: {
              type: 'linear',
              position: 'right',
              min: 50,
              max: 150,
              grid: { display: false },
              border: { display: false },
              ticks: {
                color: '#6366f1',
                font: { size: 11 },
                callback: v => v + '%',
              },
            },
          },
        },

        plugins: [barLabelsPlugin],
      })
    },
  },
}
</script>

<style scoped>
.chart-card {
  background: #ffffff;
  border-radius: 20px;
  border: 1px solid rgba(0, 0, 0, 0.06);
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.04), 0 12px 28px rgba(0, 0, 0, 0.07);
  padding: 24px 28px 20px;
  font-family: 'Inter', system-ui, sans-serif;
  width: 100%;
  max-width: 1200px;
  min-width: 350px;
}

.chart-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 20px;
  flex-wrap: wrap;
  gap: 12px;
}

.chart-tag {
  display: inline-block;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: #6366f1;
  background: rgba(99, 102, 241, 0.08);
  border: 1px solid rgba(99, 102, 241, 0.2);
  padding: 3px 10px;
  border-radius: 20px;
  margin-bottom: 6px;
}

.chart-title {
  font-size: 18px;
  font-weight: 700;
  color: #1e293b;
  letter-spacing: -0.4px;
  margin: 0 0 3px;
}

.chart-subtitle {
  font-size: 12px;
  color: #94a3b8;
  margin: 0;
  font-weight: 500;
}

.chart-header__legend {
  display: flex;
  flex-direction: column;
  gap: 6px;
  align-items: flex-end;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 12px;
  color: #64748b;
  font-weight: 500;
}

.legend-bar {
  width: 14px;
  height: 14px;
  border-radius: 4px;
  flex-shrink: 0;
}

.legend-line {
  width: 24px;
  height: 3px;
  border-radius: 2px;
  background: #6366f1;
  flex-shrink: 0;
  position: relative;

  &::after {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #6366f1;
    border: 2px solid #fff;
    box-shadow: 0 0 0 1px #6366f1;
  }
}

.chart-wrap {
  height: 360px;
  position: relative;
}

.managers-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 20px;
  padding-top: 16px;
  border-top: 1px solid #f1f5f9;
}

.manager-chip {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 12px;
  border-radius: 20px;
  border: 1px solid;
  font-size: 12px;
  font-weight: 600;
}

.chip-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.chip-name { color: #374151; }

.chip-pct {
  font-weight: 700;
  margin-left: 2px;
}
</style>
